# region: shape
def shape(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: sift
def sift(xs):
    return [v * v for v in xs]

# region: fold
def fold(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) // n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: intake
def intake(summary, bar=4):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return intake(fold(sift(shape(raw))))

